set-variable.value:
@{
        var p = context.Request.OriginalUrl.Path.ToLowerInvariant();
        var mm = System.Text.RegularExpressions.Regex.Match(p, "/deployments/([^/]+)/");
        if (!mm.Success) { return false; }
        var model = mm.Groups[1].Value.ToLowerInvariant();
        return model.StartsWith("claude") || model.StartsWith("anthropic");
    }

@{
        var list = "{{commercial-models}}";
        if (string.IsNullOrWhiteSpace(list) || list == "__none__") { return false; }
        var p = context.Request.OriginalUrl.Path.ToLowerInvariant();
        var mm = System.Text.RegularExpressions.Regex.Match(p, "/deployments/([^/]+)/");
        if (!mm.Success) { return false; }
        var model = mm.Groups[1].Value.ToLowerInvariant();
        return list.Split(',').Any(s => { var q = s.Trim().ToLowerInvariant(); return q.Length > 0 && q != "__none__" && (model == q || model.StartsWith(q)); });
    }

when.set-body:
@{
            try {
                var body = context.Request.Body?.As<JObject>(preserveContent: true);
                if (body == null) { return context.Request.Body?.As<string>(preserveContent: true); }
                var path = context.Request.OriginalUrl.Path.ToLowerInvariant();
                var mm = System.Text.RegularExpressions.Regex.Match(path, "/deployments/([^/]+)/");
                var outp = new JObject();
                outp["model"] = body["model"] ?? (JToken)(mm.Success ? mm.Groups[1].Value : "");
                var systemSb = new System.Text.StringBuilder();
                var outMsgs = new JArray();
                var msgs = body["messages"] as JArray;
                if (msgs != null) {
                    foreach (var mObj in msgs) {
                        var role = ((string)(mObj["role"]) ?? "").ToLowerInvariant();
                        var content = mObj["content"];
                        if (role == "system") {
                            if (content != null) {
                                if (content.Type == JTokenType.String) { systemSb.Append((string)content); systemSb.Append('\n'); }
                                else if (content.Type == JTokenType.Array) { foreach (var part in (JArray)content) { var t = part["text"]; if (t != null) { systemSb.Append((string)t); systemSb.Append('\n'); } } }
                            }
                            continue;
                        }
                        var anthRole = (role == "assistant") ? "assistant" : "user";
                        JToken anthContent;
                        if (content == null) { anthContent = ""; }
                        else if (content.Type == JTokenType.String) { anthContent = (string)content; }
                        else if (content.Type == JTokenType.Array) {
                            var blocks = new JArray();
                            foreach (var part in (JArray)content) { var tt = part["text"]; if (tt != null) { blocks.Add(new JObject(new JProperty("type", "text"), new JProperty("text", (string)tt))); } }
                            anthContent = blocks;
                        } else { anthContent = content.ToString(); }
                        outMsgs.Add(new JObject(new JProperty("role", anthRole), new JProperty("content", anthContent)));
                    }
                }
                outp["messages"] = outMsgs;
                if (systemSb.Length > 0) { outp["system"] = systemSb.ToString().TrimEnd(); }
                int maxTokens = 4096;
                if (body["max_completion_tokens"] != null && body["max_completion_tokens"].Type == JTokenType.Integer) { maxTokens = (int)body["max_completion_tokens"]; }
                else if (body["max_tokens"] != null && body["max_tokens"].Type == JTokenType.Integer) { maxTokens = (int)body["max_tokens"]; }
                outp["max_tokens"] = maxTokens;
                if (body["top_p"] != null && (body["top_p"].Type == JTokenType.Float || body["top_p"].Type == JTokenType.Integer)) { double tp = (double)body["top_p"]; if (tp >= 0.99) { outp["top_p"] = tp; } }
                var stop = body["stop"];
                if (stop != null) {
                    if (stop.Type == JTokenType.String) { outp["stop_sequences"] = new JArray((string)stop); }
                    else if (stop.Type == JTokenType.Array) { outp["stop_sequences"] = stop; }
                }
                var tools = body["tools"] as JArray;
                if (tools != null && tools.Count > 0) {
                    var at = new JArray();
                    foreach (var t in tools) { var fn = t["function"]; if (fn != null) { at.Add(new JObject(new JProperty("name", (string)fn["name"]), new JProperty("description", (string)(fn["description"] ?? "")), new JProperty("input_schema", fn["parameters"] ?? new JObject(new JProperty("type", "object"))))); } }
                    if (at.Count > 0) { outp["tools"] = at; }
                }
                outp["stream"] = false;
                return outp.ToString();
            } catch {
                return context.Request.Body?.As<string>(preserveContent: true);
            }
        }

otherwise.set-body:
@{
        try {
            var body = context.Request.Body?.As(preserveContent: true);
            if (body == null) { return context.Request.Body?.As(preserveContent: true); }
            var path = context.Request.OriginalUrl.Path.ToLowerInvariant();

            // (a) Reasoning-model sampling-parameter strip (always on).
            //     gpt-5 / o1 / o3 / o4 reject non-default temperature / top_p /
            //     presence_penalty / frequency_penalty with 400 unsupported_value.
            //     The deployment name lives in the URL path: /deployments//...
            var m = System.Text.RegularExpressions.Regex.Match(path, "/deployments/([^/]+)/");
            if (m.Success) {
                var model = m.Groups[1].Value;
                bool isReasoning = model.StartsWith("gpt-5") || model.StartsWith("o1") || model.StartsWith("o3") || model.StartsWith("o4");
                if (isReasoning) {
                    body.Remove("temperature");
                    body.Remove("top_p");
                    body.Remove("presence_penalty");
                    body.Remove("frequency_penalty");
                }
            }

            // (b) Streaming usage injection (opt-in, see file header).
            //     /responses calls never need it (always include usage natively).
            if (((string)context.Variables["streamUsageInjection"]) == "on" && !path.EndsWith("/responses")) {
                var stream = body["stream"];
                if (stream != null && stream.Type == JTokenType.Boolean && (bool)stream) {
                    var opts = body["stream_options"] as JObject;
                    if (opts == null) { opts = new JObject(); body["stream_options"] = opts; }
                    opts["include_usage"] = true;
                }
            }

            return body.ToString();
        } catch {
            // If the body is not JSON we can parse, forward it unchanged.
            return context.Request.Body?.As(preserveContent: true);
        }
    }

choose.when:

  @("https://{{foundry-commercial-authority-host}}/{{foundry-commercial-tenant-id}}/oauth2/v2.0/token")
  POST
  
    application/x-www-form-urlencoded
  
  @{
      return "grant_type=client_credentials"
        + "&client_id=" + System.Uri.EscapeDataString("{{foundry-commercial-client-id}}")
        + "&client_secret=" + System.Uri.EscapeDataString("{{foundry-commercial-client-secret}}")
        + "&scope=" + System.Uri.EscapeDataString("{{foundry-commercial-token-resource}}".TrimEnd('/') + "/.default");
  }

<set-variable name="commercialSpToken" value="@{
    try {
        var resp = context.Variables.ContainsKey("commercialTokenResp") ? (IResponse)context.Variables["commercialTokenResp"] : null;
        if (resp == null || resp.StatusCode != 200) { return ""; }
        var j = resp.Body.As(preserveContent: true);
        return (string)(j["access_token"]) ?? "";
    } catch { return ""; }
}" />

when.set-body:
@{
            try {
                var body = context.Response.Body.As<JObject>(preserveContent: true);
                if (body == null) { return context.Response.Body.As<string>(preserveContent: true); }
                var contentSb = new System.Text.StringBuilder();
                var toolCalls = new JArray();
                var blocks = body["content"] as JArray;
                if (blocks != null) {
                    foreach (var b in blocks) {
                        var bt = (string)b["type"];
                        if (bt == "text") { contentSb.Append((string)(b["text"] ?? "")); }
                        else if (bt == "tool_use") { toolCalls.Add(new JObject(new JProperty("id", (string)(b["id"] ?? "")), new JProperty("type", "function"), new JProperty("function", new JObject(new JProperty("name", (string)(b["name"] ?? "")), new JProperty("arguments", (b["input"] ?? new JObject()).ToString(Newtonsoft.Json.Formatting.None)))))); }
                    }
                }
                string stopReason = (string)body["stop_reason"];
                string finish = stopReason == "max_tokens" ? "length" : (stopReason == "tool_use" ? "tool_calls" : "stop");
                var msg = new JObject(new JProperty("role", "assistant"), new JProperty("content", contentSb.Length > 0 ? (JToken)contentSb.ToString() : JValue.CreateNull()));
                if (toolCalls.Count > 0) { msg["tool_calls"] = toolCalls; }
                var usage = body["usage"];
                int inTok = (int?)(usage?["input_tokens"]) ?? 0;
                int outTok = (int?)(usage?["output_tokens"]) ?? 0;
                var openai = new JObject(
                    new JProperty("id", (string)(body["id"] ?? "chatcmpl-anthropic")),
                    new JProperty("object", "chat.completion"),
                    new JProperty("created", System.DateTimeOffset.UtcNow.ToUnixTimeSeconds()),
                    new JProperty("model", (string)(body["model"] ?? "claude")),
                    new JProperty("choices", new JArray(new JObject(new JProperty("index", 0), new JProperty("message", msg), new JProperty("finish_reason", finish)))),
                    new JProperty("usage", new JObject(new JProperty("prompt_tokens", inTok), new JProperty("completion_tokens", outTok), new JProperty("total_tokens", inTok + outTok)))
                );
                return openai.ToString(Newtonsoft.Json.Formatting.None);
            } catch {
                return context.Response.Body.As<string>(preserveContent: true);
            }
        }
